class CheckoutScreen extends StatefulWidget {
  const CheckoutScreen({super.key, required this.request});

  final StayBookingRequest request;

  @override
  State<CheckoutScreen> createState() => _CheckoutScreenState();
}

class _CheckoutScreenState extends State<CheckoutScreen> {
  StayListing? _listing;
  StayQuote? _quote;
  bool _loading = true;
  String? _error;

  bool _submitting = false;

  /// Generated ONCE, when the screen opens, and reused for every attempt.
  ///
  /// This is the whole defence against a double tap or a retry after a dropped
  /// connection creating two bookings and blocking the nights twice. Moving
  /// this line into the submit handler would regenerate it per attempt and
  /// silently remove the protection, which is why it lives here and is final.
  late final String _idempotencyKey = _newKey();

  static String _newKey() {
    final int t = DateTime.now().microsecondsSinceEpoch;
    final int r = Random().nextInt(0x7FFFFFFF);
    return 'stay_${t}_$r';
  }

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final StayBookingRequest r = widget.request;
    try {
      final StayListing? listing =
          await StayListingService.instance.byId(r.listingId);
      final StayQuote quote = await StayBookingService.instance.quote(
        listingId: r.listingId,
        checkIn: r.checkIn,
        checkOut: r.checkOut,
        adults: r.adults,
        children: r.children,
        infants: r.infants,
      );
      if (!mounted) return;
      setState(() {
        _listing = listing;
        _quote = quote;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = 'We could not price this stay. Please go back and try again.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GoOutsColors.background,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0.5,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          onPressed:
              _submitting ? null : () => Navigator.of(context).pop(),
        ),
        title: Text(
          'Review your stay',
          style: GoogleFonts.inter(
            fontSize: 20,
            fontWeight: FontWeight.bold,
            color: GoOutsColors.deepNavy,
          ),
        ),
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _error != null
              ? _errorBody()
              : ListView(
                  padding: const EdgeInsets.only(bottom: 24),
                  children: [
                    _buildListingSummary(),
                    if (!_quote!.available) _buildUnavailableNotice(),
                    _buildPriceBreakdown(),
                    if (_quote!.cashback.value > 0) _buildCashbackCard(),
                    if (!_quote!.depositHold.isZero) _buildDepositInfo(),
                    _buildCancellationPolicy(),
                    _buildNoPaymentNotice(),
                  ],
                ),
      bottomSheet: (_loading || _error != null) ? null : _buildBottomAction(),
    );
  }

  Widget _errorBody() => Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Text(
            _error ?? '',
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
                fontSize: 15, color: GoOutsColors.bodyText),
          ),
        ),
      );

  // ── Summary ──────────────────────────────────────────────────────────────

  Widget _buildListingSummary() {
    final StayBookingRequest r = widget.request;
    final List<StayPhoto> photos =
        List<StayPhoto>.from(_listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b) => a.order.compareTo(b.order));

    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (photos.isNotEmpty)
            ClipRRect(
              borderRadius: BorderRadius.circular(12),
              child: Image.network(
                photos.first.url,
                width: 80,
                height: 80,
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) => const SizedBox(
                    width: 80, height: 80),
              ),
            ),
          if (photos.isNotEmpty) const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  _listing?.title ?? 'Your stay',
                  style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                    color: GoOutsColors.deepNavy,
                  ),
                ),
                if ((_listing?.address.town ?? '').isNotEmpty)
                  Text(
                    _listing!.address.town,
                    style: GoogleFonts.inter(
                        fontSize: 14, color: GoOutsColors.bodyText),
                  ),
                const SizedBox(height: 8),
                Text(
                  '${_longDate(r.checkIn)} to ${_longDate(r.checkOut)}',
                  style: GoogleFonts.inter(
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                      color: GoOutsColors.deepNavy),
                ),
                Text(
                  '${r.nights} ${r.nights == 1 ? 'night' : 'nights'} · '
                  '${r.guestSummary}',
                  style: GoogleFonts.inter(
                      fontSize: 14, color: GoOutsColors.bodyText),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  static const List<String> _months = <String>[
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  static String _longDate(DateTime d) =>
      '${d.day} ${_months[d.month - 1]} ${d.year}';

  // ── Availability ─────────────────────────────────────────────────────────
  //
  // The date screen checks availability too, but a night can be taken between
  // choosing it and arriving here. The server is the authority and says so in
  // the quote, so this is shown rather than discovered at the last tap.
  Widget _buildUnavailableNotice() {
    final int n = _quote!.unavailableNights.length;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: GoOutsColors.errorContainer,
        borderRadius: BorderRadius.circular(16),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Icon(Icons.event_busy, color: GoOutsColors.error),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              n == 0
                  ? 'These dates are no longer available. Please go back and '
                      'choose again.'
                  : '$n ${n == 1 ? 'night is' : 'nights are'} no longer '
                      'available. Please go back and choose different dates.',
              style: GoogleFonts.inter(
                  fontSize: 14,
                  height: 1.4,
                  color: GoOutsColors.onErrorContainer),
            ),
          ),
        ],
      ),
    );
  }

  // ── Price ────────────────────────────────────────────────────────────────

  Widget _buildPriceBreakdown() {
    final StayQuote q = _quote!;
    return _buildCardWrapper(
      title: 'Price breakdown',
      child: Column(
        children: [
          _buildPriceRow(
            '${q.nightlyRate.compact} × ${q.nights} '
            '${q.nights == 1 ? 'night' : 'nights'}',
            q.accommodationTotal.formatted,
          ),
          if (!q.cleaningFee.isZero)
            _buildPriceRow('Cleaning fee', q.cleaningFee.formatted),
          if (!q.serviceFee.isZero)
            _buildPriceRow('Service fee', q.serviceFee.formatted),
          const Divider(height: 32, color: GoOutsColors.dividerGray),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Total',
                style: GoogleFonts.inter(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: GoOutsColors.deepNavy,
                ),
              ),
              Text(
                q.total.formatted,
                style: GoogleFonts.inter(
                  fontSize: 18,
                  fontWeight: FontWeight.w800,
                  color: GoOutsColors.deepNavy,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildPriceRow(String label, String value) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Expanded(
            child: Text(
              label,
              style: GoogleFonts.inter(
                  fontSize: 15, color: GoOutsColors.bodyText),
            ),
          ),
          Text(
            value,
            style: GoogleFonts.inter(
                fontSize: 15, color: GoOutsColors.deepNavy),
          ),
        ],
      ),
    );
  }

  // ── Cashback ─────────────────────────────────────────────────────────────
  //
  // Shown only when the server actually returns some. The note comes from the
  // server too rather than being written here, so the terms cannot drift away
  // from what is really credited.
  Widget _buildCashbackCard() {
    final StayQuote q = _quote!;
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: GoOutsColors.primaryBlue,
        borderRadius: BorderRadius.circular(16),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Icon(Icons.savings_outlined, color: Colors.white),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'You earn ${q.cashback.formatted} cashback',
                  style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                  ),
                ),
                if (q.cashbackNote.isNotEmpty) ...[
                  const SizedBox(height: 4),
                  Text(
                    q.cashbackNote,
                    style: GoogleFonts.inter(
                      fontSize: 13,
                      height: 1.4,
                      color: Colors.white.withValues(alpha: 0.9),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ── Deposit ──────────────────────────────────────────────────────────────
  //
  // The old copy said the deposit was "a temporary hold on your card, released
  // within forty eight hours of your departure". No card is held, so that
