      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Icon(Icons.info_outline,
              color: GoOutsColors.primaryBlue, size: 24),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Damage deposit of ${_quote!.depositHold.formatted}',
                  style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                    color: GoOutsColors.deepNavy,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  'This is the most you could be asked for if damage is '
                  'reported after your stay. Nothing is taken from you now, '
                  'and the photographs you take at check-in are what protects '
