  // ── Cancellation ─────────────────────────────────────────────────────────

  Widget _buildCancellationPolicy() {
    final StayQuote q = _quote!;
    final List<String> lines = <String>[];

    if (q.fullRefundUntil != null) {
      lines.add('Full refund if you cancel before '
          '${_longDate(q.fullRefundUntil!)}.');
    }
    if (q.partialRefundPct > 0) {
      lines.add('${q.partialRefundPct}% refund after that.');
    } else if (q.fullRefundUntil != null) {
      lines.add('No refund after that date.');
    }
    if (lines.isEmpty) {
      lines.add('This host uses the '
          '${q.cancellationPolicy.isEmpty ? 'standard' : q.cancellationPolicy} '
          'cancellation policy.');
    }

    return _buildCardWrapper(
      title: 'Cancellation policy',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            lines.join(' '),
            style: GoogleFonts.inter(
              fontSize: 14,
              color: GoOutsColors.bodyText,
              height: 1.4,
            ),
          ),
          // Cancellation is not built server side yet (quoteStayCancellation
          // and cancelStayBooking do not exist). Saying so here is better than
          // a guest discovering it when they try.
          const SizedBox(height: 8),
          Text(
            'To change or cancel while we are in testing, please contact us '
            'and we will sort it out for you.',
            style: GoogleFonts.inter(
              fontSize: 13,
              fontStyle: FontStyle.italic,
              color: GoOutsColors.bodyText,
              height: 1.4,
            ),
          ),
        ],
      ),
    );
  }

