  // ── Submit ───────────────────────────────────────────────────────────────

  bool get _isInstant =>
      (_listing?.bookingMode ?? BookingMode.request) == BookingMode.instant;

  Widget _buildBottomAction() {
    final bool canSubmit = _quote!.available && !_submitting;

    return Container(
      padding: const EdgeInsets.fromLTRB(16, 20, 16, 32),
      decoration: const BoxDecoration(
        color: Colors.white,
        border: Border(top: BorderSide(color: GoOutsColors.dividerGray)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // The "Secure payment / SSL Encrypted" badges that used to sit here
          // were reassurance about a transaction that does not happen. What a
          // guest needs to know at this button is what it commits them to.
          Text(
            _isInstant
                ? 'Your booking is confirmed straight away. No payment now.'
                : 'The host has 24 hours to reply. No payment now.',
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
                fontSize: 12, color: GoOutsColors.bodyText),
          ),
          const SizedBox(height: 12),
          ElevatedButton(
            onPressed: canSubmit ? _submit : null,
            style: ElevatedButton.styleFrom(
              backgroundColor: GoOutsColors.primaryBlue,
              disabledBackgroundColor: GoOutsColors.dividerGray,
              minimumSize: const Size(double.infinity, 56),
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12)),
            ),
            child: _submitting
                ? const SizedBox(
                    height: 22,
                    width: 22,
                    child: CircularProgressIndicator(
                        strokeWidth: 2, color: Colors.white),
                  )
                : Text(
                    _isInstant ? 'Confirm booking' : 'Request to book',
                    style: GoogleFonts.inter(
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                    ),
                  ),
          ),
        ],
      ),
    );
  }

  Future<void> _submit() async {
    if (_submitting) return;
    setState(() => _submitting = true);

    final StayBookingRequest r = widget.request;
    try {
      final res = await StayBookingService.instance.create(
        listingId: r.listingId,
        checkIn: r.checkIn,
        checkOut: r.checkOut,
        adults: r.adults,
        children: r.children,
        infants: r.infants,
        idempotencyKey: _idempotencyKey,
      );

      if (!mounted) return;

      // pushReplacement, not push: going Back from the confirmation must not
      // return to a checkout screen whose button would create a second
      // booking. The idempotency key makes that harmless, but a guest should
      // not be looking at "Request to book" for a stay they have booked.
      Navigator.of(context).pushReplacementNamed(
        StayRoutes.bookingConfirmed,
        arguments: <String, dynamic>{'bookingId': res.bookingId},
      );
    } catch (e) {
      if (!mounted) return;
      setState(() => _submitting = false);
      showDialog<void>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('We could not complete this'),
          content: Text(
            e is StayFeatureNotBuilt
                ? e.toString()
                : 'Something went wrong and your booking was not made. '
                    'Nothing has been charged. Please try again.',
            style: GoogleFonts.inter(fontSize: 14, height: 1.4),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(ctx).pop(),
              child: const Text('Close'),
            ),
          ],
        ),
      );
    }
  }
}
